import{_ as t,l as s,o as e,c as i,v as r,p as l,x as n,d as p,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"优序融资","description":"","frontmatter":{"title":"优序融资","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pecking-order.md","filePath":"econ/pecking-order.md","lastUpdated":1789023840000}'),d={name:"econ/pecking-order.md"};function h(A,a,f,m,_,u){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="优序融资" tabindex="-1">优序融资 <a class="header-anchor" href="#优序融资" aria-label="Permalink to &quot;优序融资&quot;">​</a></h1><div class="epigraph"><p>若经理比市场更清楚资产价值，发股会被读成「现在被高估」；于是企业先用留存，再用债，最后才发股。</p><footer>—— Myers and Majluf, Corporate Financing and Investment Decisions When Firms Have Information That Investors Do Not Have, Journal of Financial Economics 1984</footer></div><p><a href="/econ/risk-shifting">上一课</a>（风险转移）。<a href="/econ/tradeoff-capital">权衡理论与破产成本</a>。税盾对困境成本已经给出一个内部目标 \\(D^\\ast\\)。本课缺口是 Myers（1984）立刻指出的残差：盈利企业往往杠杆更低，融资更像「有钱先用内部的」，而不像随时把杠杆调回目标。不重算税盾现值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态权衡预测：利润高、税盾用得上、破产远的企业，应当更能扛债，目标杠杆更高。观察却经常相反——盈利公司债少、现金多。若把这解释成「它们还没调回去」，必须有一种摩擦，使<strong>发股去贴近 \\(D^\\ast\\)</strong> 本身很贵。</p><p>Myers 与 Majluf（1984）把摩擦写成信息不对称：经理知道项目与资产的价值，外部投资者只看到发行决策。在<a href="/econ/akerlof-lemons">柠檬市场</a>里，卖者一开口就泄漏质量；这里「卖的」是股权。缺口不是再找一个目标比率，而是：在经理追求现有股东利益时，发行决策如何被定价，以及这如何排出融资顺序。</p><p><span class="marginnote">优序（pecking order）不是监管排序，是逆向选择下的成本排序：内部资金几乎无泄漏，无风险债泄漏少，股权泄漏最多。Myers 1984 把它对照静态权衡，称为资本结构之谜的一条解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设企业有一个正 NPV 项目，但现金不够。若按公平价格发股，项目应当上。若市场无法区分被低估与被高估的企业，发股的均衡价是混合价。被低估的企业会发现：新股东分走的价值大于项目 NPV，于是宁可不发、放弃项目。被高估的企业乐意发。市场料到这一点，发股折价更重，低估者更不愿发——逆向选择收紧。</p><p>债务的信息敏感度较低：在接近无风险时，债权人不大分享资产被低估的上行，发行折价轻。内部资金不经过发行市场，没有这层折价。于是融资顺序是：留存收益 → 债务 → 股权。权衡里的 \\(D^\\ast\\) 可以仍在，但被低估时企业不会为了贴近它去发股。</p>',10)),(e(),l(c,null,{default:n(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INFO%5B%22%E7%BB%8F%E7%90%86%E7%9F%A5%E6%83%85%2C%20%E5%B8%82%E5%9C%BA%E4%B8%8D%E7%9F%A5%E6%83%85%22%5D%20--%3E%20ISSUE%5B%22%E5%8F%91%E8%A1%8C%E5%86%B3%E7%AD%96%22%5D%0A%20%20ISSUE%20--%3E%20EQ%5B%22%E5%8F%91%E8%82%A1%3A%20%E9%AB%98%E4%BF%A1%E6%81%AF%E6%95%8F%E6%84%9F%22%5D%0A%20%20ISSUE%20--%3E%20DEBT%5B%22%E5%8F%91%E5%80%BA%3A%20%E4%BD%8E%E4%BF%A1%E6%81%AF%E6%95%8F%E6%84%9F%22%5D%0A%20%20ISSUE%20--%3E%20INT%5B%22%E5%86%85%E9%83%A8%E8%B5%84%E9%87%91%3A%20%E6%97%A0%E5%8F%91%E8%A1%8C%E6%8A%98%E4%BB%B7%22%5D%0A%20%20EQ%20--%3E%20PO%5B%22%E9%A1%BA%E5%BA%8F%3A%20%E5%86%85%E9%83%A8%2C%20%E5%80%BA%2C%20%E8%82%A1%22%5D%0A%20%20DEBT%20--%3E%20PO%0A%20%20INT%20--%3E%20PO%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>这与<a href="/econ/spence-signaling">信号发送</a>方向相反：Spence 的教育是有成本的可观察行动；Myers–Majluf 的发股是可能被拒绝的行动。企业不是用发股来分离类型，而是尽量避免走这条泄漏最大的路。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是现有股东与新股东之间的价值转移，不是破产法。经理若站在现有股东一边，就会把「被低估时发股」当成向新投资者输送。债务契约在好状态不稀释股权，所以同一信息不对称下，债的稀释更轻。累积的融资决策于是留下债务容量：内部资金耗尽后先用债，杠杆是历史残差，不是时刻对准的 \\(D^\\ast\\)。</p><p>权衡并未被逻辑取消。税盾与困境成本仍在，只是信息不对称给「朝 \\(D^\\ast\\) 调整」加了一道发行成本。两种理论预测不同的比较静态：权衡看税率与资产有形性；优序看赤字（投资减内部资金）与过去的盈利。后课的股利要处理内部资金「太多」时为什么还要吐出去——优序单独解释不了派息。</p><h3 id="债务容量不是目标杠杆" tabindex="-1">债务容量不是目标杠杆 <a class="header-anchor" href="#债务容量不是目标杠杆" aria-label="Permalink to &quot;债务容量不是目标杠杆&quot;">​</a></h3><p>优序里的「先债后股」预设还有未用的债务容量。容量用尽之后，下一口是股权或放弃项目。容量由什么决定？可以是已有的权衡 \\(D^\\ast\\)，也可以是评级门槛、契约限制。于是两种理论在操作上叠：权衡画出容量的上沿，优序决定在上沿之内按信息敏感度排序。Myers 1984 的谜题是：许多截面看起来更像优序的残差，而不是时刻对准的上沿。本课不裁判哪一篇回归赢，只禁止把优序写成「没有债务上限」。</p><p><span class="marginnote">公告效应：增发消息使价格下跌，是市场把发行读成类型信号。这与半强式 <a href="/econ/emh">EMH</a> 兼容——公开信号被立即写入价格——并不否证有效，只说明私人信息尚未进入价格（强式失败）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把优序读成「永远不发股」。项目极大、债务容量用尽、或信息对称化（招股说明书、分析师覆盖）之后，股权仍会出现。也不要把银行<a href="/econ/basel-capital">资本监管</a>下的「尽量少持普通股」写成优序：监管资本不是信息敏感证券的排序，是损失吸收顺序。</p><p>本课不写股利平滑，不写自由现金流的代理冲突。Jensen 的债务纪律与优序的「债是相对不敏感的融资」不是同一句话：一个管吐出现金，一个管如何为新项目筹资。</p><p>动态优序允许企业在被高估时发股、囤积现金，以免未来缺钱时被迫走柠檬市场。现金于是既是优序的缓冲，也是下一课代理问题的弹药。两种角色在成长企业与成熟企业之间切换，不能用同一条「现金为王」概括。</p><p>后课默认：信息不对称下融资按信息敏感度排序，杠杆可以是历史残差。内部资金过多时的代理，不是优序能单独解释的，交给股利与自由现金流。公告效应与半强式有效兼容，与强式失败兼容。</p><p>债务容量可以来自权衡上沿或评级门槛。优序在上沿之内排序，不是「没有债务上限」。</p><p>被低估时发股向新股东输送。经理站在旧股东一边就会避开这条路，于是正 NPV 也可能被放弃。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>权衡给出 \\(D^\\ast\\)；信息不对称使朝它发股变得很贵。</li><li>Myers–Majluf：发股有柠檬折价，融资优序是内部、债、股。</li><li>杠杆可以是融资历史的残差，不必是时刻对准的目标。</li><li>出处：Myers and Majluf, <em>JFE</em> 1984；Myers, <em>Journal of Finance</em> 1984。</li></ul>',16))])}const F=t(d,[["render",h]]);export{D as __pageData,F as default};
